import { getElements } from '../../utils/functional';

class UpdateProgressEls {
  constructor() {
    this.setupEls = this.setupEls.bind(this);
    this.init = this.init.bind(this);
    this.setupEls();
    this.init();
  }

  setupEls() {
    this.els = {
      progressNumberEls: getElements('.js-Progress_Number')
    };
  }

  init() {
    const currentIndex = Shopify.Checkout.step === 'contact_information' ? 1 : Shopify.Checkout.step === 'shipping_method' ? 2 : Shopify.Checkout.step === 'payment_method' ? 3 : 4;
    this.els.progressNumberEls.forEach(element => {
      element.innerHTML = currentIndex;
    });
  }

}

function updateProgressEls() {
  return new UpdateProgressEls();
}

updateProgressEls();